const input = $input.first().json;
const text = (input.text || '').toString();
const sensitiveTerms = Array.isArray(input.sensitive_terms) ? input.sensitive_terms.filter(Boolean) : [];
const pinLength = Number(input.pin_length || 6);

const mapping = {}; // token -> original
let counter = { EMAIL: 0, PHONE: 0, URL: 0, CLIENT: 0 };
let masked = text;

function nextToken(prefix) {
  counter[prefix] += 1;
  return `[${prefix}_${counter[prefix]}]`;
}

// 1. Redact standalone PIN_LENGTH digits (G16) - never put into mapping
const pinRegex = new RegExp(`\\b\\d{${pinLength}}\\b`, 'g');
masked = masked.replace(pinRegex, '[REDACTED]');

// 2. Emails
masked = masked.replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, (match) => {
  const token = nextToken('EMAIL');
  mapping[token] = match;
  return token;
});

// 3. Phone numbers: Indian 10-digit
masked = masked.replace(/(?:\+?91[\s.-]?)?\b[6-9]\d{2}[\s.-]?\d{3}[\s.-]?\d{4}\b/g, (match) => {
  const token = nextToken('PHONE');
  mapping[token] = match;
  return token;
});

// 4. URLs: http(s):// or www.
masked = masked.replace(/\b(?:https?:\/\/|www\.)[^\s]+/gi, (match) => {
  const token = nextToken('URL');
  mapping[token] = match;
  return token;
});

// 5. Sensitive terms
const sortedTerms = [...sensitiveTerms].sort((a, b) => b.length - a.length);
for (const term of sortedTerms) {
  const trimmed = (term || '').toString().trim();
  if (!trimmed) continue;
  const escaped = trimmed.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp(`\\b${escaped}\\b`, 'gi');
  masked = masked.replace(re, (match) => {
    const token = nextToken('CLIENT');
    mapping[token] = match;
    return token;
  });
}

return [{ json: { masked_text: masked, mapping } }];

const input = $input.first().json;
const mapping = input.mapping || {};
const tokens = Object.keys(mapping);

function restoreString(str) {
  if (!tokens.length) return str;
  let out = str;
  for (const token of tokens) {
    if (token === '[REDACTED]') continue; // Never restore REDACTED
    out = out.split(token).join(mapping[token]);
  }
  return out;
}

function restore(value) {
  if (typeof value === 'string') return restoreString(value);
  if (Array.isArray(value)) return value.map(restore);
  if (value && typeof value === 'object') {
    const out = {};
    for (const key of Object.keys(value)) out[key] = restore(value[key]);
    return out;
  }
  return value;
}

const source = input.data !== undefined ? input.data : input.text;
const restored = restore(source);

return [{ json: { restored } }];
